   var out=new NativeSourceControlledHealing.Output(target,receiver,hub,life,1L,40,100);check(NativeSourceControlledHealing.current(out),"detached accepted meter uses original owner/actor/receiver");set(caster,"selectedCharacter","retired-caster");check(NativeSourceControlledHealing.current(out),"already accepted meter has no new caster-role dependency");set(caster,"selectedCharacter","caster");set(owner,"selectedCharacter","replacement-owner");check(!NativeSourceControlledHealing.current(out),"accepted output rejects replaced owner role");set(owner,"selectedCharacter","owner");set(viewer,"selectedCharacter","replacement-viewer");check(!NativeSourceControlledHealing.current(out),"receiver cannot borrow old role's HPBAR");set(viewer,"selectedCharacter","viewer");set(actor,"hp",41);check(!NativeSourceControlledHealing.current(out),"later HP change cannot publish old preview");set(actor,"hp",40);set(actor,"profile",profile(200));check(!NativeSourceControlledHealing.current(out),"changed max HP cannot reuse old meter denominator");set(actor,"profile",profile(100));set(actor,"x",20);check(!NativeSourceControlledHealing.current(out),"old actor pose cannot publish after movement");set(actor,"x",0);var actorState=CombatAccess.field(CombatAccess.field(actor,"timedStatus"),"sourcePoisonLifecycle");set(actorState,"sourceNpcOwner",new Object());check(!target.current()&&!NativeSourceControlledHealing.current(out),"same actor resurrection/reuse life ABA rejected");set(actorState,"sourceNpcOwner",token);
   byte[] packet=Protocol.hitRatio(777,40,100);check(NativeSourceControlledHealing.preview(packet)&&!NativeSourceControlledHealing.preview(Protocol.hitRatio(778,40,100)),"only original controlled actor preview id suppressed");check(!NativeSourceControlledHealing.preview(null)&&!NativeSourceControlledHealing.preview(Protocol.manaPoint(40,100)),"unrelated/null preview passes original output chain");check(NativeSourceControlledHealing.packet(out,packet)&&!NativeSourceControlledHealing.packet(out,Protocol.hitRatio(777,41,100)),"final packet must match accepted actor/id/value");context.nativeSourceCubeStatusProof=out;check(NativeSourceControlledHealing.allowFrame(viewer,packet)&&!NativeSourceControlledHealing.allowFrame(owner,packet)&&!NativeSourceControlledHealing.allowFrame(viewer,Protocol.hitRatio(777,41,100)),"actual final-frame hook pairs receiver and accepted packet");set(life,"mode",NativePlayerLifetime.Mode.DRAINING);check(NativeSourceControlledHealing.current(out),"draining preserves accepted output while original cast blocks new healing");set(life,"mode",NativePlayerLifetime.Mode.STOPPED);check(!NativeSourceControlledHealing.current(out)&&!NativeSourceControlledHealing.allowFrame(viewer,packet),"stopped drops accepted output at actual final hook");set(life,"mode",NativePlayerLifetime.Mode.OPEN);set(hub,"nativeStaticMotionClosed",true);check(!NativeSourceControlledHealing.current(out),"Main close blocks accepted meter");set(hub,"nativeStaticMotionClosed",false);properties.setProperty("hpbar","false");settingsField.set(null,new NativeSourceOtherControls.Snapshot(NativeSourceDisplayPlan.Settings.read(properties),java.nio.file.Path.of("detached-readonly-controls")));check(!NativeSourceControlledHealing.current(out),"Source hpbar control suppresses recovery meter");cast.close();check(cast.nativeSourceControlledHealing==null&&NativeSourceControlledHealing.scope(cast)==null,"original cast close clears bounded actor scope");
